/* KCMC_CONTEMPORARY_FEATURE_20261002 BEGIN */
/* Warm, light public feature. Original photograph, private pages and welcome hero stay separate. */
.cw-section{padding:54px 0 64px;background:#f7f1e7;color:#243d50;color-scheme:light;border-top:1px solid #e5d8c3;border-bottom:1px solid #e5d8c3}
.cw-feature{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.12fr);background:#fffdf9;border:1px solid #daccb4;border-radius:28px;overflow:hidden;box-shadow:0 16px 42px rgba(102,77,36,.10)}
.cw-copy{padding:clamp(24px,3.4vw,42px);min-width:0;display:flex;flex-direction:column;justify-content:center}
.cw-kicker{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:.75rem;font-weight:800;line-height:1.5;text-transform:uppercase;letter-spacing:.14em;margin:0 0 20px;color:#77521c}
.cw-kicker span{display:inline-block;background:#f7ead0;border:1px solid #ab864d;border-radius:99px;padding:5px 11px;letter-spacing:.04em;color:#604315}
.cw-copy h2{font-family:Inter,ui-sans-serif,system-ui,sans-serif;font-size:clamp(2.2rem,4.2vw,3.65rem);font-weight:800;line-height:1.06;letter-spacing:-.045em;margin:0 0 22px;color:#243d50;overflow-wrap:normal}
.cw-copy h2 span{color:#925919}
.cw-intro{font-size:clamp(1.08rem,1.8vw,1.25rem);font-weight:650;color:#243d50;line-height:1.5;margin:0 0 12px}
.cw-description{font-size:1rem;line-height:1.75;color:#425767;margin:0 0 15px}
.cw-family{font-size:.94rem;line-height:1.65;color:#425767;margin:0 0 8px;padding-left:14px;border-left:2px solid #ae7a30}
.cw-actions{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0 14px}
.cw-button{display:inline-flex;align-items:center;justify-content:center;gap:14px;min-height:48px;padding:12px 18px;border:1px solid #526d7f;border-radius:12px;text-decoration:none;font:inherit;font-size:.94rem;font-weight:800;line-height:1.35;text-align:center;white-space:normal}
.cw-primary{background:#edc77f;color:#1d3547;border-color:#ae7a30}
.cw-secondary{background:#fffdf9;color:#243d50}
.cw-button:hover{background:#f8e3bc;color:#243d50;filter:none}
.cw-button:focus-visible{outline:3px solid #205b79;outline-offset:4px}
.cw-online-note{font-size:.78rem;line-height:1.6;color:#536574;margin:0;max-width:40em}
.cw-media{background:#fffdf9;min-width:0;position:relative;overflow:hidden;display:flex;align-items:center;padding:26px 26px 26px 0}
.cw-media::before,.cw-media::after{content:none}
.cw-media img{display:block;width:100%;height:auto;min-height:0;object-fit:contain;object-position:center;border-radius:18px;filter:brightness(1.16) contrast(.88) saturate(1.04)}
@media(max-width:850px){.cw-feature{grid-template-columns:1fr}.cw-media{grid-row:1;padding:20px 20px 0}.cw-media img{height:auto;min-height:0;aspect-ratio:640/344;object-fit:contain;border-radius:14px}.cw-copy{padding:30px}.cw-copy h2{font-size:clamp(2.35rem,7.2vw,3.5rem)}.cw-kicker{margin-bottom:18px}}
@media(max-width:420px){.cw-section{padding:32px 0 42px}.cw-feature{border-radius:20px}.cw-media{padding:14px 14px 0}.cw-copy{padding:23px}.cw-copy h2{font-size:clamp(1.85rem,8vw,2.7rem)}.cw-actions{display:grid;grid-template-columns:1fr}.cw-kicker{font-size:.68rem;gap:8px}.cw-intro{font-size:1.08rem}}
@media(prefers-reduced-motion:reduce){.cw-feature *{transition:none!important;animation:none!important}}
/* KCMC_CONTEMPORARY_FEATURE_20261002 END */
